/**
 * Entity identifier — a packed u32 with layout `[generation(10) | index(22)]`,
 * matching the C++ `Entity` type in `src/esengine/core/Types.hpp`
 * (`PackedId<22, 10>`).
 *
 * The 22-bit index is the slot in the registry (up to 4,194,303 live entities);
 * the 10-bit generation is bumped each time an index is recycled (up to 1,023
 * generations per slot before wrap). Comparing two raw Entity values thus
 * detects stale handles: a handle from a despawned entity will have a
 * different (generation, index) pair than any current live entity that reuses
 * the index, so `rawA !== rawB` reliably distinguishes them.
 *
 * The value is transported across the WASM boundary as a plain u32 and used
 * directly as a Map/Set key on the JS side.
 *
 * @public
 */
type Entity = number;

/**
 * JS-side invalid-entity sentinel.
 *
 * NOTE: this is `0` for legacy serialization compatibility — scenes written
 * before this packing was documented use `0` to mean "no entity reference".
 * C++ uses `0xFFFFFFFF` as its sentinel; producers/consumers at the WASM
 * boundary must translate between the two. New code should prefer
 * `isValidEntity()` over comparing against this constant directly.
 */
declare const INVALID_ENTITY: Entity;
type TextureHandle = number;
declare const INVALID_TEXTURE: TextureHandle;
type FontHandle = number;
declare const INVALID_FONT: FontHandle;
declare const INVALID_MATERIAL = 0;
/**
 * A 2D vector in world units. Plain data, so it is what a component field holds
 * and what crosses to the engine — `v2` builds one, and `scalar`/`v2` carry the
 * operations rather than the value.
 *
 * @public
 */
interface Vec2 {
    x: number;
    y: number;
}
/**
 * A 3D vector. `z` orders drawing within a layer rather than adding depth: the
 * renderer is 2D, and a Transform's z is a sort key.
 *
 * @public
 */
interface Vec3 {
    x: number;
    y: number;
    z: number;
}
/**
 * Four components, for a shader uniform or a rect passed as one value.
 *
 * @public
 */
interface Vec4 {
    x: number;
    y: number;
    z: number;
    w: number;
}
/**
 * A rotation. Stored as a quaternion because the engine composes transforms
 * with it; for 2D work, `quat`'s helpers and `quaternionToAngle2D` are the way
 * in and out of an angle.
 *
 * @public
 */
interface Quat {
    w: number;
    x: number;
    y: number;
    z: number;
}
/**
 * A colour with straight (non-premultiplied) alpha, each channel 0..1.
 *
 * @public
 */
interface Color {
    r: number;
    g: number;
    b: number;
    a: number;
}
declare const vec2: (x?: number, y?: number) => Vec2;
declare const vec3: (x?: number, y?: number, z?: number) => Vec3;
declare const vec4: (x?: number, y?: number, z?: number, w?: number) => Vec4;
declare const color: (r?: number, g?: number, b?: number, a?: number) => Color;
declare const quat: (w?: number, x?: number, y?: number, z?: number) => Quat;

